#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [0.030422264999999997, 0.17597369499999999, 0.231751845], 'basis': [[0.0, -0.0, 1.0], [0.0, 1.0, 0.0], [-1.0, 0.0, 0.0]], 'axis': [1.0, 0.0, 0.0], 'zmin': -0.067256165, 'zmax': 0.067256165, 'profiles': [{'outer': [[-0.050814464999999975, 0.016570225000000022], [-0.05132742499999998, 0.017767145000000012], [-0.051384435000000006, 0.018565075000000014], [-0.0490220622568254, 0.021312038879634405], [-0.04938952499999999, 0.023067855000000026], [-0.049446535000000014, 0.023922815000000014], [-0.044544835000000005, 0.029166475000000025], [-0.04408885499999998, 0.029565475000000008], [-0.03763998071416564, 0.030647836394475932], [-0.024661074999999977, 0.042673185], [-0.024289834999999982, 0.04299135500000001], [-0.02354742500000001, 0.042938315000000005], [-0.022380754999999974, 0.04251404500000003], [-0.020842864999999988, 0.04171862500000001], [-0.01898677500000001, 0.04055191500000002], [-0.016759514999999975, 0.03906710500000002], [-0.014373154999999999, 0.03726406500000001], [-0.011721654999999997, 0.03519590500000003], [-0.008911044999999979, 0.03291561500000001], [-0.005994374999999996, 0.030476115000000026], [-0.003077704999999986, 0.027877705000000003], [0.002649575000000015, 0.022521575000000016], [0.005354125000000015, 0.019870125000000016], [0.006056865131778268, 0.01913746705525966], [0.010710185000000011, 0.023423095000000005], [0.011452615, 0.023370105000000002], [0.012619275000000013, 0.02294589500000002], [0.014157165, 0.022150415000000007], [0.016066255, 0.020983715000000014], [0.018240495000000023, 0.01949890500000001], [0.020626855, 0.017695865000000005], [0.023278385000000013, 0.015627645000000023], [0.02608898500000001, 0.01334734500000001], [0.029005665000000014, 0.01085491500000002], [0.03192229500000002, 0.008256455000000024], [0.03483897500000002, 0.005604945000000028], [0.03764958500000001, 0.0029003850000000053], [0.04035413500000001, 0.00024886500000001477], [0.042846565, -0.002296544999999983], [0.04507383500000001, -0.004735984999999998], [0.04703596500000001, -0.006963234999999984], [0.048679885000000006, -0.008978404999999995], [0.049952615000000006, -0.010675384999999982], [0.05085414500000002, -0.012107204999999982], [0.05127838500000001, -0.013167804999999977], [0.051384435000000006, -0.013857194999999989], [0.04020728691831317, -0.02831202120463604], [0.03969636500000001, -0.03478382499999999], [0.03496563500000002, -0.040141504999999994], [0.034509625000000016, -0.04054049499999998], [0.03359767500000002, -0.040483515], [0.03197196750789489, -0.040294447775781964], [0.02932295500000001, -0.04299135499999998], [0.028467985, -0.042934364999999974], [0.027157065000000008, -0.04247836499999999], [0.02544716500000002, -0.04156644499999998], [0.023338285000000014, -0.040255524999999986], [0.021579309591987034, -0.03902832233973294], [0.007288937201522631, -0.0324232615966364], [0.004985345000000002, -0.034726834999999984], [0.004700365000000012, -0.03478382499999999], [0.003959415000000022, -0.03444186499999999], [0.002876475000000017, -0.03375787499999999], [-3.036499999997666e-05, -0.031421015], [-0.0016262849999999773, -0.029996104999999995], [-0.004419115000000001, -0.027203244999999987], [-0.005388054999999975, -0.026006324999999997], [-0.005958014999999983, -0.025208394999999995], [-0.006129014999999988, -0.02469537499999999], [-0.003976809267307538, -0.02215689206750951], [-0.004133731503628131, -0.02187791933889894], [-0.005274055, -0.023042514999999986], [-0.005673054999999982, -0.023384464999999993], [-0.006527984999999986, -0.023384464999999993], [-0.00783890499999998, -0.022871504999999986], [-0.009548814999999988, -0.02195955499999999], [-0.011657694999999996, -0.020648635], [-0.013615484949981872, -0.019328277480425003], [-0.02778192483991787, -0.012838136264546995], [-0.030010654999999997, -0.015119924999999979], [-0.030295624999999993, -0.015233914999999987], [-0.031036595, -0.014891934999999995], [-0.03211952499999998, -0.014150954999999993], [-0.033487455, -0.013125044999999974], [-0.03502635500000001, -0.011814094999999997], [-0.03662227499999998, -0.01038919499999999], [-0.03810419500000001, -0.008964284999999989], [-0.03941513499999999, -0.007596354999999999], [-0.04038406499999997, -0.006456414999999993], [-0.040954035, -0.005601504999999979], [-0.04112501499999999, -0.005088544999999972], [-0.038956359214114694, -0.0025862596185471536], [-0.04668151355649698, 0.010928498032239962], [-0.04842059500000001, 0.013036445000000008], [-0.049845534999999996, 0.014974315000000016]], 'holes': []}], 'simplify_tolerance': 2.0553774000000002e-05, 'sketch_entity_count': 95}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
